// Hunt query: Detect WinWord processes that launch PowerShell or cmd.exe
// This looks for a WinWord process whose child process name is not one of the known benign children.
// We use the "not" operator to exclude common legitimate children (e.g., explorer.exe) and then
// apply a regex on the child name to catch PowerShell/cmd executions.

let suspicious_children = ["powershell", "cmd"];

// Step 1: Find all WinWord processes
let winword_processes = SecurityEvent
    | where EventID == 4688   // Process creation event
    | where ImagePath contains "winword.exe";

// Step 2: For each WinWord process, find its child processes
let winword_children = winword_processes
    | join kind=inner (
        SecurityEvent
        | where EventID == 4688   // Child creation events (same as above)
        | where ImagePath contains "winword.exe"
        ) on $left.ParentImage equals $right.ImagePath;

// Step 3: Exclude known benign children (e.g., explorer.exe)
let benign_children = ["explorer", "svchost", "chrome", "firefox"];
winword_children = winword_children
    | extend ChildName = tostring(ChildProcessName)
    | where ChildName !in (benign_children);

// Step 4: Detect suspicious child names using regex – we only care about PowerShell/Cmd execution attempts.
let suspicious_child = suspicious_children;
suspicious_child = suspicious_child + "|| ChildName matches regex '.*\\powershell\.exe$' or ChildName matches regex '.*\\cmd\.exe$'";
winword_children = winword_children
    | extend SuspiciousChild = tostring(suspicious_child);

// Step 5: Flag any WinWord process with a suspicious child.
let flagged = winword_children
    | summarize count() by ParentImage;
flagged =
    flagged 
    | extend Alert = if(count() > 1, true, false);
SecurityAlerts 
| where Alert == true 
| project ParentImage, ChildProcessName, count()
